ALTER TABLE public.profiles ADD COLUMN active_tenant_id uuid REFERENCES public.tenants(id);
CREATE OR REPLACE FUNCTION public.is_tenant_member(p_tenant_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.tenant_memberships m JOIN public.tenants t ON t.id=m.tenant_id WHERE m.tenant_id=p_tenant_id AND m.user_id=auth.uid() AND m.status='active' AND t.status='active') $$;
CREATE OR REPLACE FUNCTION public.active_tenant_id() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.active_tenant_id FROM public.profiles p WHERE p.id=auth.uid() AND public.is_tenant_member(p.active_tenant_id) $$;
CREATE OR REPLACE FUNCTION public.has_tenant_role(p_tenant_id uuid,p_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_tenant_member(p_tenant_id) AND EXISTS(SELECT 1 FROM public.user_roles r WHERE r.tenant_id=p_tenant_id AND r.user_id=auth.uid() AND r.role=p_role) $$;
CREATE OR REPLACE FUNCTION public.can_access_tenant_module(p_tenant_id uuid,p_module text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p_tenant_id=public.active_tenant_id() AND public.is_tenant_member(p_tenant_id) AND (p_module='dashboard' OR public.has_tenant_role(p_tenant_id,'master') OR EXISTS(SELECT 1 FROM public.module_access a WHERE a.tenant_id=p_tenant_id AND a.user_id=auth.uid() AND a.module=p_module)) $$;
CREATE OR REPLACE FUNCTION public.entity_module(p_table text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE p_table WHEN 'clients' THEN 'crm' WHEN 'orders' THEN 'orders' WHEN 'order_items' THEN 'orders' WHEN 'shipments' THEN 'shipments' WHEN 'pricelist_items' THEN 'pricelist' WHEN 'payables' THEN 'finance' WHEN 'receivables' THEN 'finance' WHEN 'cash_requests' THEN 'finance' WHEN 'expenses' THEN 'finance' WHEN 'tasks' THEN 'workflow' WHEN 'team_members' THEN 'team' END $$;
CREATE OR REPLACE FUNCTION public.is_master() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_tenant_role(public.active_tenant_id(),'master') $$;
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user_id=auth.uid() AND public.has_tenant_role(public.active_tenant_id(),_role) $$;
CREATE OR REPLACE FUNCTION public.can_access(_module text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.can_access_tenant_module(public.active_tenant_id(),_module) $$;
CREATE OR REPLACE FUNCTION public.can_access_any(_modules text[]) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM unnest(_modules) m WHERE public.can_access(m)) $$;
CREATE OR REPLACE FUNCTION public.bootstrap_current_user() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); tid uuid; BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'Belum masuk'; END IF; INSERT INTO public.profiles(id,email) SELECT uid,COALESCE(auth.jwt()->>'email','') ON CONFLICT(id) DO NOTHING; SELECT active_tenant_id INTO tid FROM public.profiles WHERE id=uid; IF NOT public.is_tenant_member(tid) OR tid IS NULL THEN SELECT m.tenant_id INTO tid FROM public.tenant_memberships m JOIN public.tenants t ON t.id=m.tenant_id WHERE m.user_id=uid AND m.status='active' AND t.status='active' ORDER BY m.created_at,m.tenant_id LIMIT 1; UPDATE public.profiles SET active_tenant_id=tid WHERE id=uid; END IF; RETURN jsonb_build_object('user_id',uid,'tenant_id',tid,'role',COALESCE((SELECT role FROM public.user_roles WHERE user_id=uid AND tenant_id=tid ORDER BY role LIMIT 1),'staff'::public.app_role),'modules',COALESCE((SELECT jsonb_agg(module) FROM public.module_access WHERE user_id=uid AND tenant_id=tid),'[]'::jsonb),'tenants',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',t.id,'name',t.name,'slug',t.slug,'is_demo',t.is_demo,'settings',to_jsonb(s))) FROM public.tenant_memberships m JOIN public.tenants t ON t.id=m.tenant_id LEFT JOIN public.tenant_settings s ON s.tenant_id=t.id WHERE m.user_id=uid AND m.status='active' AND t.status='active'),'[]'::jsonb)); END $$;
CREATE OR REPLACE FUNCTION public.select_active_tenant(p_tenant_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_tenant_member(p_tenant_id) THEN RAISE EXCEPTION 'Tenant tidak berizin'; END IF; UPDATE public.profiles SET active_tenant_id=p_tenant_id WHERE id=auth.uid(); RETURN public.bootstrap_current_user(); END $$;
CREATE OR REPLACE FUNCTION public.admin_list_users() RETURNS TABLE(user_id uuid,email text,role public.app_role,modules text[]) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_master() THEN RAISE EXCEPTION 'Khusus Master'; END IF; RETURN QUERY SELECT p.id,p.email,COALESCE((SELECT r.role FROM public.user_roles r WHERE r.user_id=p.id AND r.tenant_id=public.active_tenant_id() ORDER BY r.role LIMIT 1),'staff'::public.app_role),COALESCE((SELECT array_agg(a.module ORDER BY a.module) FROM public.module_access a WHERE a.user_id=p.id AND a.tenant_id=public.active_tenant_id()),'{}'::text[]) FROM public.profiles p JOIN public.tenant_memberships m ON m.user_id=p.id WHERE m.tenant_id=public.active_tenant_id() AND m.status='active' ORDER BY p.email; END $$;
CREATE OR REPLACE FUNCTION public.admin_set_modules(p_user_id uuid,p_modules text[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_master() OR NOT EXISTS(SELECT 1 FROM public.tenant_memberships WHERE tenant_id=public.active_tenant_id() AND user_id=p_user_id AND status='active') THEN RAISE EXCEPTION 'Tidak berizin'; END IF; DELETE FROM public.module_access WHERE tenant_id=public.active_tenant_id() AND user_id=p_user_id; INSERT INTO public.module_access(tenant_id,user_id,module) SELECT public.active_tenant_id(),p_user_id,m FROM unnest(COALESCE(p_modules,'{}'::text[])) m WHERE m IN ('dashboard','crm','finance','orders','shipments','pricelist','workflow','team') ON CONFLICT DO NOTHING; END $$;
CREATE OR REPLACE FUNCTION public.admin_set_role(p_user_id uuid,p_role public.app_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_master() OR NOT EXISTS(SELECT 1 FROM public.tenant_memberships WHERE tenant_id=public.active_tenant_id() AND user_id=p_user_id AND status='active') THEN RAISE EXCEPTION 'Tidak berizin'; END IF; IF p_user_id=auth.uid() AND p_role<>'master' THEN RAISE EXCEPTION 'Tidak bisa menurunkan peran sendiri'; END IF; DELETE FROM public.user_roles WHERE tenant_id=public.active_tenant_id() AND user_id=p_user_id; INSERT INTO public.user_roles(tenant_id,user_id,role) VALUES(public.active_tenant_id(),p_user_id,p_role); END $$;
CREATE OR REPLACE FUNCTION public.create_tenant_with_master(p_slug text,p_name text,p_master_id uuid,p_is_demo boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tid uuid; BEGIN IF NOT EXISTS(SELECT 1 FROM public.platform_admins WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'Khusus operator platform'; END IF; IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_master_id) THEN RAISE EXCEPTION 'Pemilik harus mempunyai akun'; END IF; INSERT INTO public.tenants(slug,name,is_demo) VALUES(p_slug,p_name,p_is_demo) RETURNING id INTO tid; INSERT INTO public.tenant_settings(tenant_id) VALUES(tid); INSERT INTO public.tenant_memberships(tenant_id,user_id) VALUES(tid,p_master_id); INSERT INTO public.user_roles(tenant_id,user_id,role) VALUES(tid,p_master_id,'master'); RETURN tid; END $$;
CREATE OR REPLACE FUNCTION public.guard_business_row() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE tid uuid; BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Gunakan arsip, bukan hapus permanen'; END IF; IF TG_OP='UPDATE' AND NEW.tenant_id IS DISTINCT FROM OLD.tenant_id THEN RAISE EXCEPTION 'tenant_id tidak boleh diubah'; END IF; IF TG_OP='INSERT' THEN tid:=public.active_tenant_id(); IF auth.uid() IS NOT NULL THEN IF tid IS NULL OR (NEW.tenant_id IS NOT NULL AND NEW.tenant_id<>tid) THEN RAISE EXCEPTION 'Tenant tidak berizin'; END IF; NEW.tenant_id:=tid; END IF; END IF; IF TG_OP='INSERT' AND (NEW.deleted_at IS NOT NULL OR NEW.deleted_by IS NOT NULL OR NEW.delete_reason IS NOT NULL) THEN RAISE EXCEPTION 'Gunakan persetujuan pengarsipan'; END IF; IF TG_OP='UPDATE' AND (NEW.deleted_at IS DISTINCT FROM OLD.deleted_at OR NEW.deleted_by IS DISTINCT FROM OLD.deleted_by OR NEW.delete_reason IS DISTINCT FROM OLD.delete_reason) THEN IF current_user NOT IN ('postgres','supabase_admin') THEN RAISE EXCEPTION 'Gunakan fungsi arsip'; END IF; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.audit_business_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE changes jsonb; BEGIN IF TG_OP='INSERT' THEN changes:=jsonb_build_object('after',to_jsonb(NEW)); ELSE SELECT jsonb_object_agg(n.key,jsonb_build_object('before',o.value,'after',n.value)) INTO changes FROM jsonb_each(to_jsonb(NEW)) n LEFT JOIN jsonb_each(to_jsonb(OLD)) o ON o.key=n.key WHERE n.value IS DISTINCT FROM o.value; END IF; IF changes IS NOT NULL THEN INSERT INTO public.audit_logs(tenant_id,actor_id,action,entity_type,entity_id,diff) VALUES(NEW.tenant_id,auth.uid(),CASE WHEN TG_OP='UPDATE' AND NEW.deleted_at IS DISTINCT FROM OLD.deleted_at THEN CASE WHEN NEW.deleted_at IS NULL THEN 'restore' ELSE 'archive' END ELSE lower(TG_OP) END,TG_TABLE_NAME,NEW.id,changes); END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.prevent_audit_change() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Audit bersifat append-only'; END $$;
CREATE TRIGGER audit_append_only BEFORE UPDATE OR DELETE ON public.audit_logs FOR EACH ROW EXECUTE FUNCTION public.prevent_audit_change();
REVOKE UPDATE,DELETE,TRUNCATE ON public.audit_logs FROM authenticated,anon,service_role;
DO $block$ DECLARE tbl text; pol record; mod text; readers text[]; BEGIN FOREACH tbl IN ARRAY ARRAY['clients','orders','order_items','shipments','pricelist_items','payables','receivables','cash_requests','expenses','tasks','team_members'] LOOP FOR pol IN SELECT policyname FROM pg_policies WHERE schemaname='public' AND tablename=tbl LOOP EXECUTE format('DROP POLICY %I ON public.%I',pol.policyname,tbl); END LOOP; mod:=public.entity_module(tbl); readers:=CASE tbl WHEN 'clients' THEN ARRAY['crm','orders'] WHEN 'orders' THEN ARRAY['orders','shipments'] WHEN 'order_items' THEN ARRAY['orders','shipments'] WHEN 'team_members' THEN ARRAY['team','crm','workflow','orders','shipments','finance'] WHEN 'shipments' THEN ARRAY['shipments','orders'] ELSE ARRAY[mod] END; EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING (deleted_at IS NULL AND EXISTS(SELECT 1 FROM unnest(%L::text[]) m WHERE public.can_access_tenant_module(tenant_id,m)))',tbl||'_select',tbl,readers); EXECUTE format('CREATE POLICY %I ON public.%I FOR INSERT TO authenticated WITH CHECK (deleted_at IS NULL AND public.can_access_tenant_module(tenant_id,%L))',tbl||'_insert',tbl,mod); EXECUTE format('CREATE POLICY %I ON public.%I FOR UPDATE TO authenticated USING (deleted_at IS NULL AND public.can_access_tenant_module(tenant_id,%L)) WITH CHECK (deleted_at IS NULL AND public.can_access_tenant_module(tenant_id,%L))',tbl||'_update',tbl,mod,mod); EXECUTE format('CREATE POLICY %I ON public.%I FOR DELETE TO authenticated USING (false)',tbl||'_delete',tbl); EXECUTE format('REVOKE ALL ON public.%I FROM anon; REVOKE DELETE,TRUNCATE ON public.%I FROM authenticated; GRANT SELECT,INSERT,UPDATE ON public.%I TO authenticated',tbl,tbl,tbl); EXECUTE format('CREATE TRIGGER tenant_guard BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.guard_business_row()',tbl); EXECUTE format('CREATE TRIGGER business_audit AFTER INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.audit_business_change()',tbl); END LOOP; END $block$;
DO $block$ DECLARE tbl text; pol record; BEGIN FOREACH tbl IN ARRAY ARRAY['profiles','user_roles','module_access'] LOOP FOR pol IN SELECT policyname FROM pg_policies WHERE schemaname='public' AND tablename=tbl LOOP EXECUTE format('DROP POLICY %I ON public.%I',pol.policyname,tbl); END LOOP; EXECUTE format('REVOKE ALL ON public.%I FROM anon; REVOKE INSERT,UPDATE,DELETE,TRUNCATE ON public.%I FROM authenticated; GRANT SELECT ON public.%I TO authenticated',tbl,tbl,tbl); END LOOP; END $block$;
CREATE POLICY profiles_own ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());
CREATE POLICY roles_select ON public.user_roles FOR SELECT TO authenticated USING(tenant_id=public.active_tenant_id() AND public.is_tenant_member(tenant_id) AND (user_id=auth.uid() OR public.is_master()));
CREATE POLICY modules_select ON public.module_access FOR SELECT TO authenticated USING(tenant_id=public.active_tenant_id() AND public.is_tenant_member(tenant_id) AND (user_id=auth.uid() OR public.is_master()));
CREATE POLICY tenants_select ON public.tenants FOR SELECT TO authenticated USING(public.is_tenant_member(id));
CREATE POLICY membership_select ON public.tenant_memberships FOR SELECT TO authenticated USING(user_id=auth.uid() OR (tenant_id=public.active_tenant_id() AND public.is_master()));
CREATE POLICY settings_select ON public.tenant_settings FOR SELECT TO authenticated USING(public.is_tenant_member(tenant_id));
CREATE POLICY settings_update ON public.tenant_settings FOR UPDATE TO authenticated USING(tenant_id=public.active_tenant_id() AND public.is_master()) WITH CHECK(tenant_id=public.active_tenant_id() AND public.is_master());
CREATE POLICY approvals_select ON public.approval_requests FOR SELECT TO authenticated USING(tenant_id=public.active_tenant_id() AND public.is_tenant_member(tenant_id) AND (requested_by=auth.uid() OR public.is_master()));
CREATE POLICY audit_select ON public.audit_logs FOR SELECT TO authenticated USING(tenant_id=public.active_tenant_id() AND public.is_master());
CREATE POLICY counters_select ON public.document_counters FOR SELECT TO authenticated USING(public.can_access_tenant_module(tenant_id,'orders'));
CREATE OR REPLACE FUNCTION public.archive_entity(p_entity_type text,p_entity_id uuid,p_reason text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tid uuid:=public.active_tenant_id(); mod text:=public.entity_module(p_entity_type); rowtid uuid; BEGIN IF mod IS NULL OR NOT public.can_access_tenant_module(tid,mod) THEN RAISE EXCEPTION 'Modul tidak berizin'; END IF; IF length(btrim(COALESCE(p_reason,'')))=0 THEN RAISE EXCEPTION 'Alasan wajib'; END IF; EXECUTE format('SELECT tenant_id FROM public.%I WHERE id=$1 AND tenant_id=$2 AND deleted_at IS NULL FOR UPDATE',p_entity_type) INTO rowtid USING p_entity_id,tid; IF rowtid IS NULL THEN RAISE EXCEPTION 'Data tidak ditemukan'; END IF; IF NOT public.is_master() THEN INSERT INTO public.approval_requests(tenant_id,type,entity_type,entity_id,requested_by,reason) VALUES(tid,'delete',p_entity_type,p_entity_id,auth.uid(),btrim(p_reason)) ON CONFLICT DO NOTHING; RETURN 'pending'; END IF; EXECUTE format('UPDATE public.%I SET deleted_at=now(),deleted_by=$1,delete_reason=$2 WHERE id=$3 AND tenant_id=$4',p_entity_type) USING auth.uid(),btrim(p_reason),p_entity_id,tid; IF p_entity_type='orders' THEN UPDATE public.order_items SET deleted_at=now(),deleted_by=auth.uid(),delete_reason=btrim(p_reason) WHERE order_id=p_entity_id AND tenant_id=tid AND deleted_at IS NULL; UPDATE public.shipments SET deleted_at=now(),deleted_by=auth.uid(),delete_reason=btrim(p_reason) WHERE order_id=p_entity_id AND tenant_id=tid AND deleted_at IS NULL; END IF; RETURN 'archived'; END $$;
CREATE OR REPLACE FUNCTION public.restore_entity(p_entity_type text,p_entity_id uuid,p_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tid uuid:=public.active_tenant_id(); parent uuid; BEGIN IF NOT public.is_master() OR public.entity_module(p_entity_type) IS NULL THEN RAISE EXCEPTION 'Khusus Master'; END IF; IF length(btrim(COALESCE(p_reason,'')))=0 THEN RAISE EXCEPTION 'Alasan wajib'; END IF; IF p_entity_type IN ('order_items','shipments') THEN EXECUTE format('SELECT order_id FROM public.%I WHERE id=$1 AND tenant_id=$2',p_entity_type) INTO parent USING p_entity_id,tid; IF NOT EXISTS(SELECT 1 FROM public.orders WHERE id=parent AND tenant_id=tid AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Pulihkan order dahulu'; END IF; END IF; EXECUTE format('UPDATE public.%I SET deleted_at=NULL,deleted_by=NULL,delete_reason=NULL WHERE id=$1 AND tenant_id=$2 AND deleted_at IS NOT NULL',p_entity_type) USING p_entity_id,tid; INSERT INTO public.audit_logs(tenant_id,actor_id,action,entity_type,entity_id,diff) VALUES(tid,auth.uid(),'restore_reason',p_entity_type,p_entity_id,jsonb_build_object('reason',p_reason)); END $$;
CREATE OR REPLACE FUNCTION public.list_archive() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE tbl text; rows jsonb; result jsonb:='[]'::jsonb; BEGIN IF NOT public.is_master() THEN RAISE EXCEPTION 'Khusus Master'; END IF; FOREACH tbl IN ARRAY ARRAY['clients','orders','order_items','shipments','pricelist_items','payables','receivables','cash_requests','expenses','tasks','team_members'] LOOP EXECUTE format('SELECT COALESCE(jsonb_agg(jsonb_build_object(''entity_type'',%L,''id'',id,''label'',COALESCE(to_jsonb(r)->>''name'',to_jsonb(r)->>''client_name'',to_jsonb(r)->>''item_name'',to_jsonb(r)->>''vendor'',to_jsonb(r)->>''purpose'',to_jsonb(r)->>''description'',to_jsonb(r)->>''title'',to_jsonb(r)->>''ship_to'',id::text),''deleted_at'',deleted_at,''reason'',delete_reason)),''[]''::jsonb) FROM public.%I r WHERE tenant_id=$1 AND deleted_at IS NOT NULL',tbl,tbl) INTO rows USING public.active_tenant_id(); result:=result||rows; END LOOP; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.decide_approval(p_request_id uuid,p_approve boolean,p_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.approval_requests; BEGIN IF NOT public.is_master() THEN RAISE EXCEPTION 'Khusus Master'; END IF; IF length(btrim(COALESCE(p_reason,'')))=0 THEN RAISE EXCEPTION 'Alasan keputusan wajib'; END IF; SELECT * INTO r FROM public.approval_requests WHERE id=p_request_id AND tenant_id=public.active_tenant_id() AND status='pending' FOR UPDATE; IF r.id IS NULL THEN RAISE EXCEPTION 'Permintaan tidak ditemukan'; END IF; IF p_approve AND r.type='delete' THEN PERFORM public.archive_entity(r.entity_type,r.entity_id,r.reason||' / Disetujui: '||p_reason); ELSIF p_approve THEN RAISE EXCEPTION 'Persetujuan diskon/pembatalan belum tersedia pada Tahap 1'; END IF; UPDATE public.approval_requests SET status=CASE WHEN p_approve THEN 'approved' ELSE 'rejected' END,decided_by=auth.uid(),decided_at=now(),decision_reason=btrim(p_reason) WHERE id=r.id; INSERT INTO public.audit_logs(tenant_id,actor_id,action,entity_type,entity_id,diff) VALUES(r.tenant_id,auth.uid(),'approval_decision',r.entity_type,r.entity_id,jsonb_build_object('request_id',r.id,'approved',p_approve,'reason',p_reason)); END $$;
CREATE OR REPLACE FUNCTION public.get_public_pricelist() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('name',t.name,'settings',jsonb_build_object('logo_url',s.logo_url,'primary_color',s.primary_color,'contact',s.contact),'items',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',p.id,'name',p.name,'category',p.category,'unit',p.unit,'price',p.price,'updated_at',p.updated_at) ORDER BY p.category,p.name) FROM public.pricelist_items p WHERE p.tenant_id=t.id AND p.deleted_at IS NULL AND p.is_active),'[]'::jsonb)) FROM public.tenants t JOIN public.tenant_settings s ON s.tenant_id=t.id WHERE t.slug='sedyain' AND t.status='active' $$;
CREATE OR REPLACE FUNCTION public.get_shipment_tracking(p_token text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('ship_to',s.ship_to,'status',s.status,'delivery_date',s.delivery_date,'do_number',s.do_number,'received_by',s.received_by,'received_at',s.received_at,'tenant_name',t.name,'brand',jsonb_build_object('logo_url',ts.logo_url,'primary_color',ts.primary_color,'contact',ts.contact),'items',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',oi.id,'item_name',oi.item_name,'qty',oi.qty,'unit',oi.unit) ORDER BY oi.position) FROM public.order_items oi WHERE oi.order_id=s.order_id AND oi.tenant_id=s.tenant_id AND oi.deleted_at IS NULL),'[]'::jsonb)) FROM public.shipments s JOIN public.orders o ON o.id=s.order_id AND o.tenant_id=s.tenant_id JOIN public.tenants t ON t.id=s.tenant_id JOIN public.tenant_settings ts ON ts.tenant_id=t.id WHERE length(p_token)>=16 AND s.public_token=p_token AND s.deleted_at IS NULL AND o.deleted_at IS NULL AND t.status='active' $$;
CREATE OR REPLACE FUNCTION public.confirm_shipment_receipt(p_token text,p_received_by text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_id uuid; BEGIN IF length(COALESCE(p_token,''))<16 OR length(btrim(COALESCE(p_received_by,''))) NOT BETWEEN 2 AND 100 THEN RAISE EXCEPTION 'Link atau nama penerima tidak valid'; END IF; UPDATE public.shipments s SET received_by=btrim(p_received_by),received_at=now(),status='Terkirim' WHERE s.public_token=p_token AND s.received_by IS NULL AND s.deleted_at IS NULL AND EXISTS(SELECT 1 FROM public.orders o JOIN public.tenants t ON t.id=o.tenant_id WHERE o.id=s.order_id AND o.tenant_id=s.tenant_id AND o.deleted_at IS NULL AND t.status='active') RETURNING s.id INTO v_id; IF v_id IS NULL THEN RAISE EXCEPTION 'Tidak ditemukan atau sudah dikonfirmasi'; END IF; RETURN public.get_shipment_tracking(p_token); END $$;
DO $block$ DECLARE f record; BEGIN FOR f IN SELECT p.oid::regprocedure AS sig,p.proname FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon',f.sig); IF f.proname NOT IN ('guard_business_row','audit_business_change','prevent_audit_change','set_updated_at') THEN EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated,service_role',f.sig); END IF; END LOOP; END $block$;
GRANT EXECUTE ON FUNCTION public.get_public_pricelist(),public.get_shipment_tracking(text),public.confirm_shipment_receipt(text,text) TO anon;